// Kartvakt: sammenligner CT/VM i Proxmox med nettverkskartet og sjekker hull i versjonsnotatene.
// Varsler én gang per funn (static data); nullstilles når funnet er rettet.
const PVE = 'REDACTED_PVE_URL';
const PH = {Authorization: 'PVEAPIToken=REDACTED_PVE_TOKEN_ID=REDACTED_PVE_TOKEN_SECRET'};
const MAP = 'http://10.0.0.124:3020';
const res = await this.helpers.httpRequest({url: PVE + '/api2/json/cluster/resources?type=vm', headers: PH, json: true, skipSslVerification: true});
const pve = res.data.map(v => ({id: String(v.vmid), name: v.name || ''}));
const map = await this.helpers.httpRequest({url: MAP + '/', json: false});
const notes = await this.helpers.httpRequest({url: MAP + '/endringer.html', json: false});
const onMap = new Set([...String(map).matchAll(/data-vmid="(\d+)"/g)].map(m => m[1]));
const findings = {};
for (const v of pve) if (!onMap.has(v.id)) findings['mangler-' + v.id] = 'CT/VM ' + v.id + ' (' + v.name + ') finnes i Proxmox, men mangler i nettverkskartet.';
const cur = parseInt((String(map).match(/versjon <b>2\.(\d+)/) || [])[1] || '0');
const have = new Set([...(String(map) + String(notes)).matchAll(/<b>[^<]*?v2\.(\d+)/g)].map(m => parseInt(m[1])));
for (let n = cur - 30; n <= cur; n++) if (n > 0 && !have.has(n)) findings['hull-' + n] = 'Kartversjon v2.' + n + ' mangler endringsnotat (hull i loggen).';
const st = $getWorkflowStaticData('global');
const sent = st.sent || {};
const nye = [];
for (const [k, t] of Object.entries(findings)) if (!sent[k]) { sent[k] = Date.now(); nye.push(t); }
for (const k of Object.keys(sent)) if (!findings[k]) delete sent[k];
st.sent = sent;
st.sist = {tid: new Date().toISOString(), kart: cur, proxmox: pve.length, funn: Object.keys(findings).length};
if (!nye.length) return [];
return [{json: {alerts: [{labels: {name: 'kartvakt', alertname: 'kartvakt'}, annotations: {summary: 'Nettverkskart: ' + nye.length + ' avvik', description: nye.join(' ')}}]}}];
